import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/xfr16')
from h import P
P(1,[
(6090076,"Aubergine grillée au fromage","L'aubergine est un légume pauvre en glucides qui n'élève pas de façon significative la glycémie. Si vous ne trouvez pas de mini-aubergines, vous pouvez utiliser des aubergines ordinaires pour cette recette.","4","½ mini-aubergine",
["1 cuillère à soupe d'huile d'olive","2 mini-aubergines moyennes (coupées en deux dans la longueur)","1/8 cuillère à café d'ail en poudre","1/8 cuillère à café de poivre noir (moulu)","1/4 tasse de fromage mozzarella (partiellement écrémé, râpé)","1 cuillère à soupe de vinaigre balsamique","2 cuillères à café de parmesan (fraîchement râpé)"],
["Préchauffez le gril à puissance moyenne-élevée.","Arrosez uniformément les moitiés d'aubergine d'huile d'olive. Saupoudrez-les uniformément d'ail en poudre et de poivre noir.","Placez les moitiés d'aubergine sur le gril, face coupée vers le bas, et faites-les cuire 3 à 4 minutes, jusqu'à ce qu'elles soient tendres.","Retournez-les et répartissez uniformément la mozzarella sur les moitiés d'aubergine. Faites griller encore 3 à 4 minutes, jusqu'à ce que le fromage soit fondu.","Retirez les aubergines du gril et disposez-les côte à côte sur un plat de service. Arrosez uniformément de vinaigre balsamique et parsemez de parmesan."],[],[]),
(6090675,"Courge delicata rôtie au glaçage à la grenade","Laissez-vous tenter par ce mariage exquis de saveurs : notre courge delicata rôtie, nappée d'un onctueux glaçage à la grenade, transforme chaque bouchée en un accompagnement sucré-salé que vous voudrez déguster encore et encore.","6","1/2 tasse",
["2 courges delicata entières (coupées en deux, épépinées et tranchées en demi-lunes (3 lb au total))","2 cuillères à soupe d'huile d'olive","1 cuillère à soupe de vinaigre balsamique","1 cuillère à soupe de mélasse de grenade","1 cuillère à soupe de romarin frais (haché)","1/2 cuillère à café de sel","1/2 cuillère à café de poivre noir","1/4 tasse de graines de grenade (pour la garniture)"],
["Préchauffez le four à 400 degrés F.","Dans un bol, mélangez les tranches de courge delicata avec l'huile d'olive, le vinaigre balsamique, la mélasse de grenade, le romarin haché, le sel et le poivre, jusqu'à ce qu'elles soient uniformément enrobées.","Étalez les tranches de courge en une seule couche sur une plaque de cuisson recouverte de papier sulfurisé.","Faites rôtir au four préchauffé environ 20 à 25 minutes, ou jusqu'à ce que la courge soit tendre et caramélisée, en retournant les tranches à mi-cuisson.","Sortez du four et transférez dans un plat de service.","Arrosez la courge du reste de glaçage resté sur la plaque.","Garnissez de graines de grenade pour une touche de fraîcheur et de couleur.","Servez comme accompagnement savoureux et appétissant."],[],[]),
(6090763,"RECETTE BONUS : Coupes de fruits au citron","Intégrer des fruits à vos desserts leur apporte de la valeur nutritionnelle. Ces coupes de fruits plus pauvres en glucides sont un excellent choix pour les personnes qui surveillent leur diabète et la santé de leur cœur.","2","3/4 tasse de fruits + 1/4 tasse de garniture + 1/2 cuillère à soupe d'amandes",
["1/2 tasse de garniture fouettée surgelée (sans matières grasses, décongelée au réfrigérateur)","1/4 cuillère à café de zeste de citron (râpé)","2 cuillères à café de jus de citron frais","1 cuillère à soupe d'amandes (grillées à sec, en tranches, concassées)","1 kiwi entier (pelé et coupé en 4 tranches)","4 fraises moyennes (coupées en quartiers)","1/2 cuillère à café de sucre glace"],
["Dans un petit bol, mélangez délicatement la garniture fouettée, le zeste de citron et le jus de citron. Répartissez dans deux petits ramequins ou pots à crème.","Parsemez d'amandes sur la garniture fouettée. Disposez le kiwi et les fraises par-dessus. À l'aide d'une passoire fine, saupoudrez le tout de sucre glace. Servez immédiatement ou réfrigérez jusqu'au moment de servir. Si vous réfrigérez, le sucre fondra et donnera aux fruits un aspect glacé."],[],[]),
(6091518,"Brochettes de poulet grillé aux pêches et courgettes","Rehaussez vos repas adaptés au diabète avec nos savoureuses brochettes de poulet grillé pauvres en glucides, garnies de pêches juteuses et de courgettes. Régalez-vous avec ce délicieux mélange de protéines maigres, de fruits et de légumes frais, parfait pour les repas entre amis en plein air et les dîners de semaine.","4","1 brochette (3 oz de poitrine de poulet cuite, ½ pêche, ½ courgette)",
["1/4 tasse de sauce soja à teneur réduite en sodium","2 cuillères à soupe d'huile d'olive","1 gousse d'ail (hachée finement)","1 cuillère à café de gingembre frais (râpé)","1 lb de poitrines de poulet désossées et sans peau (coupées en morceaux)","2 courgettes moyennes (coupées en rondelles de ½ pouce)","4 brochettes entières en bois ou en métal","2 pêches entières (coupées en morceaux de ½ pouce)"],
["Dans un bol, fouettez ensemble la sauce soja, l'huile d'olive, le miel, l'ail et le gingembre.","Placez le poulet, les pêches et les courgettes dans un grand sac refermable ou un plat peu profond et versez la marinade dessus. Fermez et réfrigérez au moins 1 heure, jusqu'à une nuit entière.","Préchauffez le gril (ou une poêle-gril d'intérieur) à puissance moyenne-élevée. Enfilez le poulet, les pêches et les courgettes sur les brochettes. Jetez le reste de marinade.","Faites griller 10 à 15 minutes, en retournant de temps en temps, jusqu'à ce que le poulet soit bien cuit et que les pêches soient tendres."],[],[]),
(6092225,"Edamame rôtis au sel et au poivre","Les edamame rôtis au sel et au poivre sont non seulement une collation savoureuse et croquante, mais aussi nutritive. Les edamame sont riches en protéines et en fibres, ce qui en fait une option saine pour ceux qui recherchent une gourmandise rassasiante et équilibrée.","4","1/2 tasse",
["2 tasses d'edamame frais écossés (décongelés, sans sel ajouté)","1 cuillère à soupe d'huile d'olive","1/4 cuillère à café de sel de mer","1/2 cuillère à café de poivre noir"],
["Préchauffez le four à 400 degrés F. Recouvrez une plaque de cuisson de papier sulfurisé.","Dans un bol, mélangez les edamame décongelés avec l'huile d'olive jusqu'à ce qu'ils soient uniformément enrobés.","Étalez les edamame en une seule couche sur la plaque préparée. Saupoudrez uniformément de sel de mer et de poivre noir. Remuez pour bien répartir l'assaisonnement.","Faites rôtir au four préchauffé environ 15 minutes, ou jusqu'à ce que les edamame soient légèrement croustillants, en remuant une ou deux fois pendant la cuisson pour une cuisson uniforme. Si vous aimez le piquant, saupoudrez les edamame rôtis de flocons de piment rouge avant de servir.","Sortez du four et laissez les edamame refroidir légèrement avant de servir."],[],[]),
(6093298,"Pudding de graines de chia au citron et aux framboises","Cette collation originale mais facile à préparer apporte des acides gras oméga-3 bons pour le cœur grâce aux graines de chia, ainsi que d'autres atouts nutritionnels comme les protéines et les fibres.\n\nRetrouvez cette recette et bien d'autres dans The Diabetes Superfoods Cookbook and Meal Planner.","4","1/3 tasse de pudding + 1/2 tasse de framboises",
["1/4 tasse de graines de chia","1 tasse de lait d'amande à la vanille non sucré","1/2 cuillère à café de zeste de citron","1 1/2 cuillère à café de jus de citron","1 cuillère à soupe de miel","2 tasses de framboises"],
["Dans un petit saladier, fouettez ensemble tous les ingrédients sauf les framboises. Placez le mélange au réfrigérateur pendant au moins une heure, jusqu'à ce que les graines de chia absorbent le liquide et que la préparation prenne la consistance d'un pudding.","Pour servir, mettez 1/3 tasse de pudding dans un petit bol avec 1/2 tasse de framboises."],[],[]),
(6093808,"Pain de blé","Informations nutritionnelles pour 1 tranche (1 oz) de pain de blé","1","1 tranche",
["1 tranche de pain 100 % blé"],[],[],[]),
(6094992,"Courge spaghetti façon pad thaï","La courge spaghetti est une alternative pauvre en glucides aux nouilles de riz traditionnelles du pad thaï. Une tasse de courge spaghetti cuite ne contient que 10 grammes de glucides totaux, contre 42 grammes pour les nouilles de riz !","4","1 tasse",
["1 courge spaghetti moyenne (environ 2,5 lb)","1 cuillère à soupe d'huile d'olive","1/2 tasse d'oignon vert (ciboule) (haché)","2 carottes moyennes (coupées en petits dés)","1 courgette moyenne (coupée en petits dés)","1/2 tasse de champignons de Paris blancs (hachés)","1 gousse d'ail (hachée finement)","1/2 cuillère à café de gingembre moulu","2 cuillères à soupe de sauce pad thaï (préparée)","8 oz de crevettes (cuites, décortiquées, sans la queue)","1/4 tasse de coriandre fraîche (hachée)"],
["Coupez la courge spaghetti en deux dans la longueur et retirez les graines. Placez la courge dans un plat allant au micro-ondes, face coupée vers le bas. Couvrez sans serrer avec un couvercle en laissant une ouverture pour la vapeur. Faites cuire au micro-ondes 10 à 15 minutes, en faisant pivoter le plat toutes les 5 minutes. La courge est cuite lorsqu'elle est molle au toucher. Réservez.","Faites chauffer l'huile d'olive dans une grande sauteuse à feu moyen-vif. Ajoutez les oignons verts, les carottes, la courgette et les champignons et faites sauter 5 à 7 minutes. Ajoutez l'ail et faites sauter 30 secondes. Ajoutez le gingembre et la sauce pad thaï et faites chauffer 2 minutes. Mélangez bien.","À l'aide d'une fourchette, détachez la chair de la courge spaghetti. Ajoutez les « nouilles » de courge spaghetti et les crevettes dans la poêle avec les légumes. Faites chauffer encore 2 minutes et mélangez bien. Garnissez de coriandre hachée."],[],[]),
(6097149,"Poulet rôti à la coriandre et au citron vert, version économique","La coriandre et le citron vert forment une combinaison de saveurs fraîche et acidulée dans ce plat de poulet. Nous partons d'un poulet entier que nous découpons en 2 poitrines, 2 cuisses, 2 pilons et 2 ailes. Les bouchers des supermarchés découpent généralement un poulet entier pour vous, ou vous pouvez acheter 2 à 3 lb de morceaux de poulet.","6","1/2 poitrine, 1 cuisse, ou 1 pilon + 1 aile",
["1 pulvérisation, 0,25 g d'aérosol de cuisson antiadhésif","1 poulet entier (d'environ 2 1/2 lb) (coupé en 8 morceaux)","2 cuillères à soupe de coriandre (hachée)","1 citron vert entier (zeste et jus)","1 cuillère à soupe de miel","2 gousses d'ail (hachées finement)","1/2 cuillère à café de poivre noir","1/2 cuillère à café de sel"],
["Préchauffez le four à 375 degrés F. Graissez un plat allant au four avec l'aérosol de cuisson.","Retirez la peau du poulet et disposez les morceaux en une seule couche dans le plat.","Dans un petit bol, fouettez ensemble la coriandre, le zeste de citron vert, le jus de citron vert, le miel, l'ail, le poivre noir moulu et le sel. Versez uniformément le mélange sur le poulet et faites cuire au four 45 à 50 minutes, ou jusqu'à ce que la température interne du plus gros morceau de poulet atteigne 165 degrés."],[],[]),
(6098453,"Bol de yaourt aux fruits rouges et aux graines de chia","Ce bol coloré réunit du yaourt grec nature onctueux sans matières grasses, des fruits rouges naturellement sucrés et le léger croquant des graines de chia. C'est un petit-déjeuner ou une collation frais, rassasiant et d'une belle simplicité, à préparer dans un seul bol.","1","1 1/2 tasse",
["1 tasse de yaourt grec nature sans matières grasses","3/4 tasse de fruits rouges variés","2 cuillères à soupe de graines de chia"],
["Il suffit de verser, saupoudrer et mélanger tous les ingrédients, sans aucune cuisson."],[],[]),
(6098853,"Bol barbecue « Aimez vos restes »","Manger des restes ne signifie pas forcément manger le même repas deux fois ! Faites preuve de créativité et réutilisez vos restes dans un bol complet. Utilisez les céréales, légumes et protéines qui vous restent au réfrigérateur et réunissez le tout avec une sauce barbecue relevée. Vous pouvez utiliser une sauce barbecue du commerce (choisissez une marque sans sucre ajouté !) ou essayer cette recette de sauce barbecue rapide et facile sucrée aux fruits.\n\nCe bol s'accorde aussi bien avec une ambiance texane, mexicaine ou asiatique. Des protéines déjà cuites ? Essayez la poitrine de poulet, la poitrine de dinde ou le tofu. Des légumes non féculents déjà cuits ? Essayez le brocoli, la courgette ou les poivrons. Des céréales complètes déjà cuites ? Essayez l'épeautre, le riz brun ou le sorgho. Une autre sauce que le barbecue ? Essayez la salsa, la sauce asiatique aux cacahuètes ou un peu de sauce piquante. Les possibilités sont infinies !","1","1 bol",
["1 1/2 tasse de jeunes pousses d'épinards frais","3 oz de protéines maigres cuites, comme du poulet (coupées en bouchées)","1/3 tasse de céréales complètes cuites, comme du quinoa, du riz ou de l'orge","1 1/2 tasse de légumes non féculents cuits, comme du brocoli (coupés en bouchées)","1 1/2 cuillère à soupe de sauce barbecue sans sucre ajouté","2 cuillères à soupe de coriandre fraîche","1 ou 2 quartiers de citron vert"],
["Mettez les épinards dans un bol allant au micro-ondes. Disposez par-dessus les protéines maigres, les légumes et les céréales complètes. Arrosez de sauce barbecue.","Faites chauffer au micro-ondes à puissance maximale pendant 1 minute 15 secondes, ou jusqu'à ce que ce soit chaud. Rectifiez l'assaisonnement.","Parsemez de coriandre et servez avec le ou les quartiers de citron vert."],[],[]),
(6099038,"Bisque de potiron","Veloutée, riche et crémeuse, cette bisque de potiron est un délicieux ajout à un dîner de fête. La purée de potiron en conserve est riche en antioxydants, et les graines de potiron constituent une bonne source de graisses insaturées saines.","6","2/3 tasse",
["1 cuillère à soupe d'huile d'olive","1 oignon moyen (haché finement)","2 gousses d'ail (hachées finement)","1 cuillère à café de poudre de curry","1/2 cuillère à café de coriandre moulue","1/4 cuillère à café de piment de Cayenne","1/4 cuillère à café de sel","1/4 cuillère à café de poivre noir (de préférence fraîchement moulu)","3 tasses de bouillon de poulet à faible teneur en sodium","15 oz de potiron en conserve","1 tasse de moitié-moitié sans matières grasses","1 cuillère à café de substitut de sucre faible en calories","1/4 tasse de graines de potiron","1/4 tasse de ciboulette fraîche (hachée finement)"],
["Dans une grande casserole, faites chauffer l'huile à feu moyen. Ajoutez l'oignon et faites-le revenir 5 à 7 minutes, jusqu'à ce qu'il soit tendre. Ajoutez l'ail, la poudre de curry, la coriandre, le piment de Cayenne, le sel et le poivre et faites revenir 1 minute.","Ajoutez le bouillon et portez à ébullition. Baissez le feu et laissez mijoter à découvert 20 minutes.","Ajoutez le potiron et laissez mijoter 10 minutes. À l'aide d'un mixeur plongeant, mixez la soupe jusqu'à ce qu'elle soit lisse. Ou versez avec précaution la soupe chaude (par portions) dans un mixeur et mixez jusqu'à ce qu'elle soit lisse ; remettez ensuite la soupe dans la casserole.","Ajoutez le moitié-moitié et l'édulcorant sucre-stévia et laissez mijoter à feu doux 2 minutes. Servez à la louche dans des bols individuels. Garnissez chaque bol de belles pincées de graines de potiron et de ciboulette."],[],[]),
(6099939,"Gratin mexicain de quinoa","Ce plat riche en nutriments est un excellent accompagnement. Il apporte des protéines grâce au quinoa et aux haricots, ainsi que quelques légumes !","12","1/3 tasse",
["1 pulvérisation, 0,25 g d'aérosol de cuisson antiadhésif","3 cuillères à café d'huile d'olive","1 oignon moyen (en dés)","1 poivron vert moyen (en dés)","2 gousses d'ail (hachées finement)","2 tasses de quinoa","1 tasse de bouillon de poulet à faible teneur en sodium (faible teneur en sodium, réduit en matières grasses)","2 1/2 tasses d'eau","1 boîte (15,5 oz) de haricots noirs (sans sel ajouté, rincés et égouttés)","1 boîte (14,5 oz) de tomates en dés en conserve","1 cuillère à soupe de chili en poudre","1 cuillère à café de cumin","1/4 cuillère à café de poivre noir","1 tasse de fromage cheddar (râpé, à teneur réduite en matières grasses)"],
["Préchauffez le four à 350 degrés F. Graissez un plat allant au four de 9 x 14 pouces avec l'aérosol de cuisson.","Faites chauffer l'huile d'olive dans une casserole à feu moyen-vif. Ajoutez les oignons et le poivron vert et faites revenir jusqu'à ce que les oignons deviennent translucides. Ajoutez l'ail et faites revenir encore 30 secondes.","Ajoutez tous les ingrédients restants sauf le cheddar. Portez à ébullition. Réduisez le feu et laissez mijoter 20 minutes.","Versez le mélange de quinoa dans le plat et étalez-le uniformément. Garnissez de cheddar et faites cuire 10 minutes, jusqu'à ce que le fromage soit fondu et légèrement doré."],[],[]),
(6100173,"Soupe persane froide au concombre et à la ciboulette","Si vous aimez le tzatziki, cette recette pleine de saveur en est une version soupe, acidulée et fraîche. Le concombre râpé ainsi que l'ajout original de thé la rendent rafraîchissante, presque digne d'un spa.","4","1 tasse",
["2 concombres persans entiers ou 1 concombre anglais (non pelés, râpés grossièrement)","1 1/4 tasse de yaourt grec nature sans matières grasses","3 brins de ciboulette fraîche (hachés finement)","1 cuillère à soupe de menthe fraîche (finement hachée)","1 échalote moyenne (hachée finement)","1 gousse d'ail (hachée finement)","1 1/2 cuillère à soupe de vinaigre balsamique blanc ou de vinaigre de champagne","3/4 cuillère à café de poivre noir (fraîchement moulu)","1/2 cuillère à café de sel de mer","2/3 tasse de thé vert non sucré ou de thé vert au jasmin (préparé avec 1 sachet de thé) (refroidi)"],
["Dans un bol moyen, mélangez le concombre, le yaourt, 2 cuillères à soupe de ciboulette, la menthe, l'échalote, l'ail, le vinaigre, le poivre, le sel et le thé. Rectifiez l'assaisonnement. Réfrigérez jusqu'au moment de servir.","Répartissez la soupe dans de petites tasses ou de petits bols individuels. Servez garni du reste de ciboulette, soit 1 cuillère à café."],[],[]),
(6101503,"Rollatini d'aubergine au fromage","Ces rollatini d'aubergine plus légers offrent le réconfort de la cuisine italienne classique avec moins de glucides et moins de graisses saturées que l'aubergine à la parmigiana traditionnelle. Des tranches fines d'aubergine sont rôties au lieu d'être panées, puis garnies d'un mélange savoureux de ricotta, de mozzarella et de chou frisé, d'oignon et d'ail sautés pour plus de fibres et de saveur. Le résultat est un plat principal végétarien adapté au diabète, qui s'intègre bien dans une alimentation pauvre en matières grasses tout en restant copieux et rassasiant.","6","3 rollatini d'aubergine avec la sauce",
["2 aubergines moyennes (environ 2 lb au total, coupées dans la longueur en lanières de 1/4 pouce d'épaisseur. Vous devriez obtenir 18 lanières.)","1 cuillère à café d'aérosol de cuisson à l'huile d'olive","1/2 cuillère à café d'huile d'olive","1 petit oignon jaune (environ 4 oz, haché finement)","2 gousses d'ail (hachées finement)","4 tasses de chou frisé (haché, grosses tiges retirées)","3/4 tasse de fromage ricotta partiellement écrémé","1/4 tasse de fromage mozzarella râpé à faible teneur en matières grasses","1/4 tasse de yaourt grec nature sans matières grasses","1/4 cuillère à café de poivre noir","1/2 cuillère à café d'assaisonnement italien séché","2 tasses de tomates concassées sans sel ajouté","1/4 cuillère à café de flocons de piment rouge broyés","1/4 tasse de feuilles de basilic déchirées (tassées)"],
["Préchauffez le four à 400 degrés F. Disposez les tranches d'aubergine en une seule couche sur deux plaques de cuisson à rebords. Enduisez légèrement les deux faces d'aérosol de cuisson à l'huile d'olive. Faites rôtir 18 à 22 minutes, en retournant à mi-cuisson, jusqu'à ce qu'elles soient tendres et souples. Sortez du four et laissez refroidir.","Faites chauffer le reste de 1/2 cuillère à café d'huile d'olive dans une grande poêle à feu moyen. Ajoutez l'oignon haché et faites cuire 4 à 5 minutes, jusqu'à ce qu'il soit ramolli. Ajoutez l'ail et faites cuire 30 secondes. Ajoutez le chou frisé et faites cuire en remuant 3 à 4 minutes, jusqu'à ce qu'il soit complètement flétri et que l'humidité se soit évaporée. Retirez du feu et laissez refroidir légèrement.","Dans un bol moyen, mélangez la ricotta, la mozzarella, le yaourt grec, le poivre noir et l'assaisonnement italien. Incorporez le mélange de chou frisé refroidi jusqu'à ce qu'il soit uniformément réparti.","Étalez 2 tasses de tomates concassées uniformément au fond d'un plat allant au four de 9 x 13 pouces. Déposez 1/4 tasse de garniture à une extrémité de chaque tranche d'aubergine et roulez bien serré. Disposez les rouleaux, côté jointure vers le bas, dans le plat sur les tomates.","Couvrez sans serrer de papier d'aluminium et faites cuire à 375 degrés F pendant 30 minutes. Découvrez et poursuivez la cuisson 20 à 25 minutes de plus, jusqu'à ce que l'aubergine commence à dorer et que la sauce tomate frémisse légèrement. Saupoudrez de flocons de piment rouge broyés, si désiré.","Laissez reposer le plat 5 minutes avant de servir. Garnissez de basilic déchiré et répartissez en 6 portions, avec 3 rollatini par assiette et de la sauce versée sur le dessus."],[],[]),
])
